    "label",
    input.targetLabelId,
  );

  const issuesRelabelled = await labelRepo.mergeLabelAssignments(
    input.orgId,
    input.sourceLabelId,
    input.targetLabelId,
  );

  return { label: target, issuesRelabelled };
}

export async function findLabel(
  orgId: OrgId,
  labelId: LabelId,
): Promise<IssueLabel | null> {
  const row = getDb()
    .select()
    .from(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, labelId)))
    .get();
  return row ? toLabel(row) : null;
}

/**
 * Moves every issue↔label row from `sourceLabelId` onto `targetLabelId`
 * (archived issues included), drops duplicate joins, then deletes the source
 * label. The target label row is left untouched. Returns how many issues
 * carried the source label before the move.
 */
export async function mergeLabelAssignments(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  const db = getDb();
  return db.transaction((tx) => {
    const sourceRows = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all();

    const targetRows = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, targetLabelId),
        ),
      )
      .all();

    const alreadyOnTarget = new Set(targetRows.map((row) => row.issueId));
    const overlap = sourceRows
      .map((row) => row.issueId)
      .filter((issueId) => alreadyOnTarget.has(issueId));

    if (overlap.length > 0) {
      tx.delete(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
            inArray(issueLabels.issueId, overlap),
          ),
        )
        .run();
    }

    tx.update(issueLabels)
      .set({ labelId: targetLabelId })
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return sourceRows.length;
  });
}

